// Estructura: for (inicialización; condición; incremento)
for (int i = 0; i < 10; i++)
{
    Debug.Log("Iteración: " + i);
}
// i va de 0 a 9 (10 iteraciones)

// Iterar un array de enemigos
for (int i = 0; i < enemies.Length; i++)
{
    enemies[i].TakeDamage(10);
}

// Recorrer en reversa
for (int i = enemies.Length - 1; i >= 0; i--)
{
    if (enemies[i].isDead) enemies.RemoveAt(i);
}

// while: repite MIENTRAS la condición sea true
int attempts = 0;
while (attempts < 3)
{
    bool success = TryConnect();
    if (success) break;
    attempts++;
}

// foreach: para colecciones (más seguro que for con índices)
foreach (GameObject enemy in enemies)
{
    enemy.SetActive(false);
}

// ADVERTENCIA: bucle infinito (evitar)
